#include "Entity/Object/Player/player.h"
#include <algorithm>
Player::Player(Vector3 p):Entity(p){camera_.position={p.x,p.y+1.6F,p.z};camera_.target={p.x,p.y+1.6F,p.z-1};camera_.up={0,1,0};camera_.fovy=75;camera_.projection=CAMERA_PERSPECTIVE;Add(BlockType::Dirt,20);Add(BlockType::OakLog,5);Add(BlockType::Stone,10);}void Player::Update(float){position_={camera_.position.x,camera_.position.y-1.6F,camera_.position.z};}void Player::Draw()const{}
int Player::Count(BlockType t)const{int n=0;for(auto&s:inventory_)if(s.type==t)n+=s.count;return n;}void Player::Add(BlockType t,int n){for(auto&s:inventory_)if(s.type==t&&s.count<10){int a=std::min(n,10-s.count);s.count+=a;n-=a;if(!n)return;}for(auto&s:inventory_)if(s.type==BlockType::Air){int a=std::min(n,10);s={t,a};n-=a;if(!n)return;}}bool Player::Remove(BlockType t,int n){if(Count(t)<n)return false;for(auto&s:inventory_)if(s.type==t){int a=std::min(n,s.count);s.count-=a;n-=a;if(!s.count)s={};if(!n)return true;}return true;}
